param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='mission-multicombat-v1270i',[string]$Candidate='candidate-npc-combat-v1214ah',[string]$Guard='script_spawner_streets_windmill_guard_01',[int]$FightMs=26000)
# 1270 (stage 4, #14): sustained multi-enemy fight on Edge of the World, both players at once. Generated by make_mission_multicombat_v1270.py
# from Test-WindowTraversal-v1235f.ps1 (product controller, modal clearing, Dunwall fixture restoration).
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$lab="$root/outputs/d2-coop-lab"
$out=Join-Path $PSScriptRoot $Take
$mutex=[Threading.Mutex]::new($false,'Local\D2CoopLab_NativeOperation_01a11a65');$owned=$false;$dirty=$false;$failure=$null;$pids=@{};$captures=[Collections.Generic.List[object]]::new();$rows=[Collections.Generic.List[object]]::new();$samplers=[Collections.Generic.List[object]]::new()
function Save($p,$v){$v|ConvertTo-Json -Depth 15|Set-Content -LiteralPath $p}
function C($r,$cmd){& "$lab/Send-D2Command.ps1" -Role $r -Command $cmd -WaitConsumed -ReceiptTimeoutMs 8000|Out-Null}
function S($r,$suffix=''){for($i=0;$i-lt40;$i++){try{return(Get-Content "$root/work/lab-instances/$r/coop-status.json$suffix" -Raw -ErrorAction Stop|ConvertFrom-Json -ErrorAction Stop)}catch{Start-Sleep -Milliseconds 25}};throw "Status unavailable $r"}
function Q($r,$mode,$arg=0){for($i=0;$i-lt8;$i++){$raw=if($arg){& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode $arg}else{& "$lab/bin/d2_runtime_probe.exe" $pids[$r] $mode};if(!$LASTEXITCODE){return($raw|ConvertFrom-Json)};Start-Sleep -Milliseconds 50};throw "Native query failed $r $mode"}
function F($r){for($i=0;$i-lt6;$i++){$raw=& "$lab/bin/d2_runtime_probe.exe" $pids[$r] --focus;if(!$LASTEXITCODE){return($raw|ConvertFrom-Json)};Start-Sleep -Milliseconds 50};throw "Focus query failed $r"}
function I($r,[string]$b='Neutral',[int]$ms=100){& "$lab/Send-D2Input.ps1" -Role $r -Button $b -DurationMs $ms|Out-Null}
function ProductStatus($r){S $r '.product.json'}
function Live($r){$s=S $r;$m=S $r '.movement.json';$x=S $r '.shadow-stream.json';$a=$s.probeRenderPosition;$b=$s.remotePosition
 $d=if($a-and$b){[Math]::Sqrt(($a[0]-$b[0])*($a[0]-$b[0])+($a[1]-$b[1])*($a[1]-$b[1])+($a[2]-$b[2])*($a[2]-$b[2]))}else{999}
 @{follow=$s.probeFollowEnabled;distance=[Math]::Round($d,3);product=(S $r '.product.json').result;bank=[bool]$m.active;bankVersion=$m.version;stream=[bool]($x.armed-and$x.ready);ok=($s.probeActorHandle-and$s.probeFollowEnabled-and$d-lt1.0-and$m.active-and$x.armed-and$x.ready-and$s.remoteFresh)}}
function WaitLive($tag,$limit=30000){$w=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 300;$p=@{host=(Live host);client=(Live client)};$ok=$p.host.ok-and$p.client.ok}while(!$ok-and$w.ElapsedMilliseconds-lt$limit);$p.ok=$ok;$p.waitMs=$w.ElapsedMilliseconds;Save "$out/live-$tag.json" $p;return $p}
$modals=[Collections.Generic.List[object]]::new()
function ClearModals($tag){for($i=0;$i-lt4;$i++){$hit=$false;foreach($r in 'host','client'){$l=(S $r).localGameLogicState;if($l-in12,2){$hit=$true;$modals.Add(@{tag=$tag;role=$r;logic=$l;at=[DateTime]::Now.ToString('o')});I $r B 200;Start-Sleep -Milliseconds 300;I $r}};if(!$hit){return};Start-Sleep -Milliseconds 900}}
function Pitch($r,$deg){try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $r -Pitch $deg -Quick|Out-Null;$true}catch{$false}}
function WaitCaptures(){foreach($c in @($captures)){try{if(!$c.WaitForExit(40000)){Stop-Process -Id $c.Id}}catch{}};$captures.Clear()}
function Living($r){@((Q $r '--world-npcs').npcs)}
function Dist2($a,$b){[Math]::Sqrt(([double]$a[0]-[double]$b[0])*([double]$a[0]-[double]$b[0])+([double]$a[1]-[double]$b[1])*([double]$a[1]-[double]$b[1]))}
function Outcome($r,$spawner){$n=@((Q $r '--world-npcs').npcs|Where-Object spawnerName -eq $spawner);if(!$n.Count){return 'absent'};$h=try{Q $r '--health' $n[0].handle}catch{$null}
 if(!$h){return 'unreadable'};if($h.current-le0){'dead'}elseif($h.ownerSuppressed){'unconscious'}else{'alive'}}
function Fight{
 $npcs=Living host;$anchor=@($npcs|Where-Object spawnerName -eq $Guard);if($anchor.Count-ne1){throw "Guard $Guard missing"};$ap=$anchor[0].position
 $group=@($npcs|Where-Object {$_.unique-and$_.spawnerName-match'guard|watch|officer|soldier'-and(Dist2 $_.position $ap)-lt16-and[Math]::Abs([double]$_.position[2]-[double]$ap[2])-lt3})
 Save "$out/guards-before.json" @($group|ForEach-Object {@{spawner=$_.spawnerName;definition=$_.definition;position=$_.position;handle=$_.handle}})
 if(!$group.Count){throw 'No guard group near the anchor'}
 C host ('setviewpos {0:F3} {1:F3} {2:F3} -90 0' -f [double]$ap[0],([double]$ap[1]+4),([double]$ap[2]+1.7));C client ('setviewpos {0:F3} {1:F3} {2:F3} -90 0' -f ([double]$ap[0]-2),([double]$ap[1]+4),([double]$ap[2]+1.7))
 Start-Sleep -Milliseconds 1500;ClearModals 'placed'
 foreach($r in 'host','client'){$hwnd=(Get-Process -Id $pids[$r]).MainWindowHandle.ToInt64()
  $args=@('-hide_banner','-loglevel','warning','-nostdin','-f','lavfi','-i',"gfxcapture=hwnd=${hwnd}:capture_cursor=0:max_framerate=30:width=-2:height=-2,hwdownload,format=bgra",'-t',[string][Math]::Ceiling($FightMs/1000+6),'-an','-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-fps_mode','passthrough','-movflags','+faststart',"$out/fight-$r.mp4")
  $captures.Add((Start-Process (Get-Command ffmpeg).Source -ArgumentList $args -WindowStyle Hidden -RedirectStandardError "$out/fight-$r-capture.log" -PassThru))}
 $handles=@{};foreach($r in 'host','client'){$all=Living $r;$handles[$r]=@{};foreach($g in $group){$m=@($all|Where-Object spawnerName -eq $g.spawnerName);if($m.Count){$handles[$r][$g.spawnerName]=$m[0].handle}}}
 $samples=[Collections.Generic.List[object]]::new();$watch=[Diagnostics.Stopwatch]::StartNew();$aimAt=@{host=-9999;client=-9999};$hitAt=@{host=-9999;client=-9999}
 while($watch.ElapsedMilliseconds-lt$FightMs){$t=$watch.ElapsedMilliseconds
  foreach($r in 'host','client'){
   if($t-$aimAt[$r]-ge2500){$aimAt[$r]=$t;try{$me=(Q $r '--player').candidatePosition;$near=@(Living $r|Where-Object {$_.unique-and$_.spawnerName-in@($group|ForEach-Object spawnerName)}|Sort-Object {Dist2 $_.position $me})
     $alive=@($near|Where-Object {$h=try{Q $r '--health' $_.handle}catch{$null};$h-and$h.current-gt0-and!$h.ownerSuppressed})
     if($alive.Count){$gp=$alive[0].position;$yaw=[Math]::Atan2([double]$gp[1]-[double]$me[1],[double]$gp[0]-[double]$me[0])*180/[Math]::PI;$d=Dist2 $gp $me
      $tx=[double]$me[0];$ty=[double]$me[1];if($d-gt1.8){$k=($d-1.4)/$d;$tx=$tx+([double]$gp[0]-$tx)*$k;$ty=$ty+([double]$gp[1]-$ty)*$k}
      C $r ('setviewpos {0:F3} {1:F3} {2:F3} {3:F2} 0' -f $tx,$ty,([double]$me[2]+1.7),$yaw)}}catch{}}
   if($t-$hitAt[$r]-ge700){$hitAt[$r]=$t;& "$lab/Send-D2Input.ps1" -Role $r -RightTrigger 255 -DurationMs 180|Out-Null}}
  $row=[ordered]@{ms=$t}
  foreach($r in 'host','client'){$nc=try{S $r '.npc-combat.json'}catch{$null};$na=try{S $r '.npc-attack.json'}catch{$null};$ns=try{S $r '.npc-stream.json'}catch{$null};$st=S $r
   $row[$r]=[ordered]@{logic=$st.localGameLogicState;health=$(try{(Q $r '--health' 1).current}catch{$null});combat=$nc.result;attack=$na.result;attackBindings=@($na.bindings|Where-Object {$_.ready}).Count;attackApplied=$na.applied;attackSent=$na.sent;enabled=$nc.enabled;committed=$nc.committed;applied=$nc.applied;rejected=$nc.rejected;deaths=$nc.deaths;retired=$nc.channelsRetired;added=$nc.channelsAdded;lastRetire=$nc.lastRetire;
    guards=@($group|ForEach-Object {$h=$handles[$r][$_.spawnerName];if($h){$v=try{Q $r '--health' $h}catch{$null};"$($_.spawnerName.Substring($_.spawnerName.Length-2)):$(if($v){[Math]::Round([double]$v.current,1)}else{'?'})"}});
    ready=@($nc.entries|Where-Object {$_.enabled-and$_.ready}).Count;stream=@($ns.entries|ForEach-Object {"$($_.handle):$($_.result)$(if($_.unconscious){':u'})"})}}
  $samples.Add([pscustomobject]$row);Start-Sleep -Milliseconds 250}
 Start-Sleep -Seconds 4;WaitCaptures
 Save "$out/fight-samples.json" @($samples)
 foreach($q in 'host','client'){foreach($suffix in '.npc-stream.json','.npc-combat.json','.npc-attack.json','.product.json'){try{Copy-Item -LiteralPath "$root/work/lab-instances/$q/coop-status.json$suffix" -Destination "$out/fight-$q$suffix" -ErrorAction Stop}catch{}}}
 $outcomes=@($group|ForEach-Object {[ordered]@{spawner=$_.spawnerName;host=(Outcome host $_.spawnerName);client=(Outcome client $_.spawnerName)}})
 Save "$out/outcomes.json" $outcomes
 $row=[ordered]@{guards=$group.Count;outcomes=$outcomes;samples=$samples.Count;passed=$false;failure=$null;checks=[Collections.Generic.List[string]]::new()}
 $row.stuck=@($samples|Where-Object {$_.host.combat-eq'waiting_for_actors'-and$_.host.enabled}).Count
 $row.hostCommitted=($samples|Select-Object -Last 1).host.committed;$row.clientRequests=($samples|Select-Object -Last 1).client.committed
 $row.minHealth=@{host=($samples|ForEach-Object {$_.host.health}|Measure-Object -Minimum).Minimum;client=($samples|ForEach-Object {$_.client.health}|Measure-Object -Minimum).Minimum}
 $mismatch=@($outcomes|Where-Object {$_.host-ne$_.client});$changed=@($outcomes|Where-Object {$_.host-ne'alive'})
 $died=@($samples|Where-Object {$_.host.logic-eq13-or$_.client.logic-eq13});$row.gameOverSamples=$died.Count
 if($died.Count){$row.failure="A player died (Game Over) at $($died[0].ms) ms; the fight is inconclusive"}
 elseif($mismatch.Count){$row.failure="Guard outcomes differ: "+(($mismatch|ForEach-Object {"$($_.spawner) host $($_.host) client $($_.client)"})-join '; ')}
 elseif(!$changed.Count){$row.failure='No guard was defeated'}else{$row.passed=$true;$row.checks.Add("$($changed.Count) of $($group.Count) guards defeated; every guard ends in the same state in both worlds")}
 $rows.Add([pscustomobject]$row)
}
function WaitGameplay($limitMs){$w=[Diagnostics.Stopwatch]::StartNew();$log=[Collections.Generic.List[object]]::new();$last=@{host=0;client=0}
 do{Start-Sleep -Milliseconds 500;$ready=$true
  foreach($r in 'host','client'){$s=S $r;$log.Add(@{ms=$w.ElapsedMilliseconds;role=$r;logic=$s.localGameLogicState;pending=$s.localPendingGameLogicState;map=$s.localMapId})
   if($s.localGameLogicState-ne1-or$s.localPendingGameLogicState){$ready=$false}
   if($s.localGameLogicState-in8,15-and$w.ElapsedMilliseconds-gt5000-and$w.ElapsedMilliseconds-$last[$r]-gt1500){I $r A 300;$last[$r]=$w.ElapsedMilliseconds}
   elseif($s.localGameLogicState-eq5-and$w.ElapsedMilliseconds-$last[$r]-gt4000){I $r X 3000;$last[$r]=$w.ElapsedMilliseconds}
   elseif($s.localGameLogicState-eq12-and$w.ElapsedMilliseconds-$last[$r]-gt1500){I $r B 200;$last[$r]=$w.ElapsedMilliseconds}}
  if($ready-and(S host).localMapId-ne(S client).localMapId){$ready=$false}
 }while(!$ready-and$w.ElapsedMilliseconds-lt$limitMs);return @{ready=$ready;log=@($log)}}
try{
 try{$owned=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owned=$true};if(!$owned){throw 'Native operation active'}
 if(Test-Path $out){throw 'Unique take required'};New-Item -ItemType Directory $out|Out-Null;Copy-Item $PSCommandPath "$out/run-script.ps1"
 foreach($r in 'host','client'){$l=Get-Content "$root/work/lab-instances/$r/launch.json" -Raw|ConvertFrom-Json;if((Get-Process -Id $l.pid).Path-ne(Join-Path $root 'work/asset-game/Dishonored2.exe')){throw 'Wrong isolated process'};$pids[$r]=$l.pid;if((S $r).localGameLogicState-ne1){throw 'Gameplay required'}}
 $pin=Get-Content "$root/work/movement-integration/$Candidate/identity.json" -Raw|ConvertFrom-Json;if((Get-FileHash "$root/work/asset-game/dinput8.dll").Hash-ne$pin.dll){throw "Expected $Candidate"}
 Save "$out/identity.json" @{candidate=$Candidate;dll=$pin.dll;guard=$Guard;fightMs=$FightMs}
 $dirty=$true
 foreach($r in 'host','client'){I $r;foreach($cmd in 'coop_checkpoint_sync off','coop_usable_sync off','coop_door_sync off','coop_coin_sync off','coop_npc_stream off'){C $r $cmd}}
 C host 'campaign campaign/edge_of_the_world/eotw.mapinfo low corvo';C client 'campaign campaign/edge_of_the_world/eotw.mapinfo low emily'
 $g=WaitGameplay 300000;Save "$out/load-log.json" $g.log;if(!$g.ready){throw 'Both instances did not reach the same mission gameplay'}
 foreach($r in 'host','client'){C $r $(if($r-eq'client'){'coop_checkpoint_delay 1500'}else{'coop_checkpoint_delay 0'})}
 foreach($r in 'host','client'){C $r 'coop_product_auto on'}
 $wt=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 500;$ok=(ProductStatus host).result-eq'armed'-and(ProductStatus client).result-eq'armed'}while(!$ok-and$wt.ElapsedMilliseconds-lt60000)
 if(!$ok){throw 'Product controller not armed'}
 $armedLive=WaitLive 'armed' 60000;if(!$armedLive.ok){foreach($q in 'host','client'){Save "$out/movement-armed-$q.json" (S $q '.movement.json')};throw 'Partner presentation not live after arming'}
 Fight
 Save "$out/modals.json" @($modals)
 $bad=@($rows|Where-Object {!$_.passed})
 if($bad.Count){$failure=($bad|ForEach-Object {$_.failure})-join '; '}
 Save "$out/verified.json" @{passed=!$bad.Count;cases=$rows.Count}
}catch{$failure=$_.Exception.Message;Save "$out/failure.json" @{message=$failure;stack=$_.ScriptStackTrace}}
finally{
 if($owned){
  $errors=[Collections.Generic.List[string]]::new()
  foreach($s in $samplers){try{if(!$s.HasExited){Stop-Process -Id $s.Id}}catch{}}
  foreach($c in @($captures)){try{if(!$c.HasExited-and!$c.WaitForExit(30000)){Stop-Process -Id $c.Id}}catch{}}
  if($dirty){
   $cw=[Diagnostics.Stopwatch]::StartNew()
   do{$off=$true;foreach($r in 'host','client'){try{I $r;C $r 'coop_observer_camera off';C $r 'coop_product_auto off';C $r 'coop_movement_resume off';foreach($cmd in 'coop_usable_sync off','coop_door_sync off','coop_coin_sync off','coop_npc_stream off','coop_shadow_stream off','coop_movement_bank off','coop_trigger_mirror off'){C $r $cmd};C $r 'coop_checkpoint_sync off';$st=S $r
     if((S $r '.reset.json').enabled){$off=$false;if($st.localGameLogicState-in8,15){I $r A 300}elseif($st.localGameLogicState-eq2){I $r B 200}}}catch{}}
    if(!$off){Start-Sleep -Milliseconds 1500}}while(!$off-and$cw.ElapsedMilliseconds-lt60000)
   foreach($r in 'host','client'){try{if((S $r).localGameLogicState-in2,12){I $r B 200;Start-Sleep -Milliseconds 800}}catch{}}
   try{& "$root/work/PrepareShadowSword.ps1" -EvidencePath "$out/restored-setup.json"|Out-Null;& "$PSScriptRoot/Restore-LabNoteInventory-v779.ps1" -Baseline "$root/work/natural-moveset/native-coin-reward-v786c" -Evidence "$out/note-restoration"|Out-Null}catch{$errors.Add($_.Exception.Message)}
  }
  foreach($r in 'host','client'){try{$s=S $r;$hp=Q $r '--health' 1;if($s.localGameLogicState-ne1-or$hp.current-ne56-or!$s.remoteFresh){throw 'Final gameplay/health/transport not restored'}}catch{$errors.Add("${r}: $($_.Exception.Message)")}}
  foreach($f in Get-Content "$root/work/movement-integration/protected-save-hashes-before-v4.json" -Raw|ConvertFrom-Json){if((Get-FileHash -LiteralPath $f.Path).Hash-ne$f.Hash){$errors.Add('Protected file changed')}}
  Save "$out/restoration.json" @{passed=(!$errors.Count);errors=@($errors)};if($errors.Count-and!$failure){$failure=$errors-join '; '}
  Save "$out/result.json" @{passed=(!$failure);failure=$failure;cases=@($rows);scope='Stage 4 sustained multi-enemy fight on Edge of the World: both players fight the Wall of Light guard group at once under the product controller; guard outcomes compared in both worlds, combat session and player health sampled; Dunwall fixture restored.'}
  $mutex.ReleaseMutex()
 };$mutex.Dispose()
}
Get-Content "$out/result.json";if($failure){throw $failure}
